   const apply=button(rt('apply'),()=>finish(true)),cancel=button(rt('cancel'),()=>finish(false));apply.disabled=preview.canRestore!==true||!/^([a-f0-9]{64})$/i.test(preview.sourceHash||'')||(preview.protectedFiles||[]).length>0;
